head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldcom91000";
scwin.pnl_2 = null;
scwin.pnl_remnd = null;
scwin.pnl_seg = null;
scwin.grd_audtwrtrpt_fnc = null;
scwin.grd_audtwrtrpt_fnc2 = null;
