scwin.showload = null;
scwin.panel_chk = null;
scwin.panel_form_cd = null;
scwin.Grd_com_isur = null;
scwin.panel_ifrs = null;
scwin.gShowloadYn = '';
scwin.gIsurCd = undefined;
scwin.gComAbbrv = undefined;
scwin.gLdMktTp = undefined;
scwin.gMktTp = undefined;
scwin.gDepCd = undefined;
scwin.vDigitalYn = "N";
scwin.dts_corp_basic = null;
scwin.dts_Krx_Emp_Info = null;
scwin.dts_Charge_Info = null;
scwin.dts_fncstat = null;
scwin.dts_inqdsclreq_cnt = null;
scwin.dts_corpnmhistory_list = null;
scwin.dts_backdoor_list = null;
scwin.dts_admisu_list = null;
scwin.dts_nfaith_list = null;
scwin.MxDataSet_com_isur = null;
scwin.dts_trdstop_stat = null;
scwin.dts_audtwrtrpt_fnc = null;
scwin.dts_Charge_Info2 = null;
scwin.dts_audtwrtrpt_fnc2 = null;
scwin.dts_Print = null;
scwin.dts_Corp_Print = null;
scwin.dts_EmpInfo = null;
scwin.dts_Nfaith = null;
scwin.dts_audtwrtrpt_fnc3 = null;
scwin.dts_seg_hist = null;
scwin.dts_remnd_list = null;
scwin.fn_ReadBasicInfo = null;
scwin.fn_ReadDsclInfo = null;
scwin.fn_ReadFncDataInfo = null;
scwin.fn_getEmpNoInfo = null;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.pnl_2 = $c.util.getComponent('pnl_2');
        scwin.pnl_remnd = $c.util.getComponent('pnl_remnd');
        scwin.pnl_seg = $c.util.getComponent('pnl_seg');
        scwin.grd_audtwrtrpt_fnc = $c.util.getComponent('grd_audtwrtrpt_fnc');
        scwin.grd_audtwrtrpt_fnc2 = $c.util.getComponent('grd_audtwrtrpt_fnc2');
        scwin.panel_opt1 = $c.util.getComponent('panel_opt1');
        scwin.panel_advisor = $c.util.getComponent('panel_advisor');
        scwin.showload = $c.util.getComponent('showload');
        scwin.panel_chk = $c.util.getComponent('panel_chk');
        scwin.panel_form_cd = $c.util.getComponent('panel_form_cd');
        scwin.Grd_com_isur = $c.util.getComponent('Grd_com_isur');
        scwin.panel_ifrs = $c.util.getComponent('panel_ifrs');
        scwin.dts_corp_basic = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsCorpBasic')) : $c.util.getComponent('dtsCorpBasic');
        scwin.dts_Krx_Emp_Info = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Krx_Emp_Info')) : $c.util.getComponent('dts_Krx_Emp_Info');
        scwin.dts_Charge_Info = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Charge_Info')) : $c.util.getComponent('dts_Charge_Info');
        scwin.dts_fncstat = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsFncstat')) : $c.util.getComponent('dtsFncstat');
        scwin.dts_inqdsclreq_cnt = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsInqdsclreqCnt')) : $c.util.getComponent('dtsInqdsclreqCnt');
        scwin.dts_corpnmhistory_list = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsCorpnmhistoryList')) : $c.util.getComponent('dtsCorpnmhistoryList');
        scwin.dts_backdoor_list = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsBackdoorList')) : $c.util.getComponent('dtsBackdoorList');
        scwin.dts_admisu_list = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsAdmisuList')) : $c.util.getComponent('dtsAdmisuList');
        scwin.dts_nfaith_list = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsNfaithList')) : $c.util.getComponent('dtsNfaithList');
        scwin.MxDataSet_com_isur = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('MxDataSetComIsur')) : $c.util.getComponent('MxDataSetComIsur');
        scwin.dts_trdstop_stat = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsTrdstopStat')) : $c.util.getComponent('dtsTrdstopStat');
        scwin.dts_audtwrtrpt_fnc = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsAudtwrtrptFnc')) : $c.util.getComponent('dtsAudtwrtrptFnc');
        scwin.dts_Charge_Info2 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Charge_Info2')) : $c.util.getComponent('dts_Charge_Info2');
        scwin.dts_audtwrtrpt_fnc2 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsAudtwrtrptFnc2')) : $c.util.getComponent('dtsAudtwrtrptFnc2');
        scwin.dts_Print = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Print')) : $c.util.getComponent('dts_Print');
        scwin.dts_Corp_Print = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Corp_Print')) : $c.util.getComponent('dts_Corp_Print');
        scwin.dts_EmpInfo = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_EmpInfo')) : $c.util.getComponent('dts_EmpInfo');
        scwin.dts_Nfaith = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_Nfaith')) : $c.util.getComponent('dts_Nfaith');
        scwin.dts_audtwrtrpt_fnc3 = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsAudtwrtrptFnc3')) : $c.util.getComponent('dtsAudtwrtrptFnc3');
        scwin.dts_seg_hist = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsSegHist')) : $c.util.getComponent('dtsSegHist');
        scwin.dts_remnd_list = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsRemndList')) : $c.util.getComponent('dtsRemndList');
        scwin.fn_ReadBasicInfo = scwin.tx_script_dts_corp_basic;
        scwin.fn_ReadDsclInfo = scwin.tx_script_dts_backdoor_list;
        scwin.fn_ReadFncDataInfo = scwin.tx_script_dts_audtwrtrpt_fnc;
        scwin.fn_getEmpNoInfo = scwin.tx_script_dts_EmpInfo;
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldcom91000.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.showObj(scwin.panel_ifrs);
        scwin.isDigitalCheck();
        scwin.getParentValue();
        scwin.showObj(scwin.panel_chk, false);
        scwin.showObj(ipt_txbExcntMsg, false);
        fn_com_isur(ipt_txbIsurCd, ipt_txbComAbbrv);
        $c.util.getComponent('tab_corpinfo').setSelectedIndex(1);
        scwin.gDepCd = $c.session.getUserInfo("depCd");
        if (scwin.gDepCd !== '' && scwin.gDepCd === 'ZSYS') {
            scwin.showObj(scwin.panel_form_cd, true);
        } else {
            scwin.showObj(scwin.panel_form_cd, false);
        }
        if (scwin.gMktTp === "1") {
            $c.util.getComponent("ipt_textbox1").setValue("공시담당자(정)");
            $c.util.getComponent("ipt_textbox2").setValue("공시담당자(부)");
            scwin.showObj(scwin.pnl_seg, false);
            scwin.showObj(scwin.pnl_remnd, false);
            scwin.pnl_2.style.height = "650";
        } else {
            if (scwin.gMktTp === "2") {
                scwin.pnl_2.style.height = "970";
                scwin.showObj(scwin.pnl_seg, true);
                scwin.showObj(scwin.pnl_remnd, true);
            } else {
                scwin.pnl_2.style.height = "650";
                scwin.showObj(scwin.pnl_seg, false);
                scwin.showObj(scwin.pnl_remnd, false);
            }
        }
        scwin.showload.setStyle("display", "none");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldcom91000.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_corp_basic_onloaderror
 * @description dts_corp_basic onloaderror 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.dts_corp_basic_onloaderror = function () {
    try {
        $c.win.alert(scwin.dts_corp_basic);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldcom91000.dts_corp_basic_onloaderror" });
    }
};

/**
 * @method
 * @name dts_corp_basic_onloadcompleted
 * @description dts_corp_basic onloadcompleted 이벤트
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_corp_basic_onloadcompleted = async function (rowcount) {
    try {
        if (scwin.dts_corp_basic.errorMsg) {
            await $c.win.alert(scwin.dts_corp_basic.errorMsg);
        } else {
            scwin.gMktTp = scwin.dts_corp_basic.getCellData(1, "MKT_TP_CD");
            scwin.gComAbbrv = ipt_txbComAbbrv.value;
            if (scwin.gMktTp === '1') {
                ipt_txbLabel3.setValue('[관리종목]');
                scwin.showObj(scwin.panel_opt1, true);
                scwin.showObj(scwin.panel_advisor, false);
            } else {
                if (scwin.gMktTp === '6') {
                    ipt_txbLabel3.setValue('[관리종목]');
                    scwin.showObj(scwin.panel_opt1, false);
                    scwin.showObj(scwin.panel_advisor, true);
                } else {
                    ipt_txbLabel3.setValue('[관리종목]');
                    scwin.showObj(scwin.panel_opt1, false);
                    scwin.showObj(scwin.panel_advisor, false);
                }
            }
            if (scwin.gMktTp === '2') {
                let excnt_msg = "";
                const EXMPT_OBJ_DISCLS_YN = scwin.dts_corp_basic.getCellData(1, "EXMPT_OBJ_DISCLS_YN");
                const EXCNT_DISCLS_CORP_YN = scwin.dts_corp_basic.getCellData(1, "EXCNT_DISCLS_CORP_YN");
                if (EXMPT_OBJ_DISCLS_YN === 'Y' && EXCNT_DISCLS_CORP_YN === 'Y') {
                    excnt_msg = '사전확인면제법인 / 공시우수법인';
                } else {
                    if (EXMPT_OBJ_DISCLS_YN === 'Y') {
                        excnt_msg = '사전확인면제법인';
                    } else {
                        if (EXCNT_DISCLS_CORP_YN === 'Y') {
                            excnt_msg = '공시우수법인';
                        }
                    }
                }
                ipt_txbExcntMsg.setValue(excnt_msg);
                scwin.showObj(ipt_txbExcntMsg, true);
            } else {
                ipt_txbExcntMsg.setValue('');
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldcom91000.dts_corp_basic_onloadcompleted" });
    }
};

