/**
 * @method
 * @name dts_fncstat_onloadcompleted
 * @description txb_yy_r1 을(를) 값을 넣는다 · txb_yy_r3 을(를) 값을 넣는다 · txb_yy_r4 을(를) 값을 넣는다 외
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_fncstat_onloadcompleted = function (rowcount) {
    try {
        $c.util.getComponent("ipt_txbYyR1").setValue(ipt_txbYyL1.value);
        $c.util.getComponent("ipt_txbYyR3").setValue(ipt_txbYyL3.value);
        $c.util.getComponent("ipt_txbYyR4").setValue(ipt_txbYyL4.value);
        if (ipt_txbBigYn.value === 'Y') {
            ipt_txbTotasst1.style.color = "#FF0000";
        }
        if (ipt_txb_IFRS_YN.value === 'Y') {
            scwin.showObj(rd_rdo_FS, true);
            if (ipt_txb_CIFRS_ASST_AMT1.value === '' && ipt_txb_CIFRS_DEBT_AMT1.value === '' && ipt_txb_CIFRS_CAP1.value === '' && ipt_txb_CIFRS_CAPI1.value === '' && ipt_txb_CIFRS_SALES1.value === '' && ipt_txb_CIFRS_BZ_PROFT_AMT1.value === '' && ipt_txb_CIFRS_BFTAX_NETPL_AMT1.value === '' && ipt_txb_CIFRS_NETINCM_AMT1.value === '') {
                scwin.setFncStat('2');
                rd_rdo_FS.setValue('2');
            } else {
                scwin.setFncStat('1');
                rd_rdo_FS.setValue('1');
            }
        } else {
            scwin.showObj(rd_rdo_FS, false);
        }
        scwin.showload.setStyle("display", "none");
        scwin.gShowloadYn = 'Y';
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldcom91000.dts_fncstat_onloadcompleted" });
    }
};

