        if (scwin.dts_audtwrtrpt_fnc3.errorMsg) {
            await $c.win.alert(scwin.dts_audtwrtrpt_fnc3.errorMsg);
        } else {
            if (rowcount > 0) {
                const MsgTxt = "(" + scwin.dts_audtwrtrpt_fnc3.getCellData(1, "FS_ACNT_TP_NM") + ")" + scwin.dts_audtwrtrpt_fnc3.getCellData(1, "ADT_OPN_CUR") + ", [공시일:" + scwin.dts_audtwrtrpt_fnc3.getCellData(1, "ORGN_DISCLS_DDTM") + "]";
                $c.util.getComponent("ipt_tbxAdtOpnCur").setValue(MsgTxt);
            } else {
                $c.util.getComponent("ipt_tbxAdtOpnCur").setValue('-');
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldcom91000.dts_audtwrtrpt_fnc3_onloadcompleted" });
    }
};

