/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function () {
    scwin.gLdMktTp = $c.session.getUserInfo("market");
    const pvd = scwin.getProvider();
    if (pvd != null) {
        scwin.gIsurCd = pvd.gIsurCd;
        $c.util.getComponent("ipt_txbIsurCd").setValue(scwin.gIsurCd);
        if ($c.str.trim(scwin.gIsurCd).length === 5) {
            scwin.fn_ReadBasicInfo();
        }
    }
};

/**
 * @method
 * @name checkCond
 * @description check Cond 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCond = async function () {
    scwin.gIsurCd = ipt_txbIsurCd.getValue();
    $c.util.getComponent('tab_corpinfo').setSelectedIndex(1);
    if (scwin.gIsurCd.length !== 5) {
        await $c.win.alert("회사코드 5자리를  입력하십시오.");
        $c.util.getComponent("ipt_txbIsurCd").focus();
        return;
    }
    if (scwin.gMktTp === "2") {
        scwin.pnl_2.style.height = "970";
        scwin.showObj(scwin.pnl_seg, true);
        scwin.showObj(scwin.pnl_remnd, true);
    } else {
        scwin.pnl_2.style.height = "650";
        scwin.showObj(scwin.pnl_seg, false);
        scwin.showObj(scwin.pnl_remnd, false);
    }
    scwin.fn_ReadBasicInfo();
};

