/**
 * @method
 * @name getDateYmd
 * @description get Date Ymd 처리
 * @param {*} d d
 * @returns {void}
 * @hidden N
 */
scwin.getDateYmd = function (d) {
    if (d === "") {
        return "-";
    }
    return "'" + d.substring(2, 4) + "." + d.substring(4, 6) + "." + d.substring(6, 8);
};

/**
 * @method
 * @name getDateY
 * @description get Date Y 처리
 * @param {*} d d
 * @returns {void}
 * @hidden N
 */
scwin.getDateY = function (d) {
    return "'" + d.substring(2, d.length);
};

/**
 * @method
 * @name timer
 * @description timer 처리
 * @returns {void}
 * @hidden N
 */
scwin.timer = function () {
    const date = new Date();
    const curYear = date.getYear();
    const curMonth = (date.getMonth()) + 1;
    const curDay = date.getDate();
    return curYear + "-" + curMonth + "-" + curDay;
};

/**
 * @method
 * @name numberWithCommas
 * @description number With Commas 처리
 * @param {*} type type
 * @param {Number} n n
 * @returns {void}
 * @hidden N
 */
scwin.numberWithCommas = function (type, n) {
    if (type === "EMP_CNT") {
        if (n !== "") {
            return n.replace(/\B(?=(\d{3})+(?!\d))/g, ',') + "명";
        }
        return n;
    } else {
        if (type === "ACC_PNLT") {
            if (n === "0") {
                return "0.0점";
            }
            const parts = n.toString().split(".");
            return parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ",") + (parts[1] ? "." + parts[1] : "") + "점";
        }
    }
    return n;
};

/**
 * @method
 * @name getBlankCheck
 * @description get Blank Check 처리
 * @param {*} type type
 * @param {Object} param param
 * @returns {void}
 * @hidden N
 */
scwin.getBlankCheck = function (type, param) {
    if (type === "MKTCAP") {
        if (param !== "") {
            return param + " 억원";
        }
    }
    if (param === "") {
        return "-";
    }
    return param;
};

/**
 * @method
 * @name getSiseNgonsiDataDefault
 * @description get Sise Ngonsi Data Default 처리
