};

/**
 * @method
 * @name getSiseNgonsiData
 * @description get Sise Ngonsi Data 처리
 * @returns {void}
 * @hidden N
 */
scwin.getSiseNgonsiData = function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.fil.compareFromToDate2
    if ($c.fil.compareFromToDate2(cal_edt_FromDate, cal_edt_ToDate) === false) {
        return;
    }
    const myUrl = "/DsclChart.do?method=getChartContents" + "&isurcd=" + ipt_txbIsurCd.getValue() + "&fromdate=" + cal_edt_FromDate.text + "&todate=" + cal_edt_ToDate.text + "&dscltype=" + slc_cmbDisclsTP.valueOfIndex("VALUE", slc_cmbDisclsTP.Index);
    $("#panel_1").load(myUrl).fadeIn("slow");
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function () {
    vCurDate = $c.date.formatDate("yyyymmdd");
    $c.util.getComponent('cal_edt_FromDate').setValue($c.date.addMonth(vCurDate.substring(0, 4), vCurDate.substring(4, 6), vCurDate.substring(6, 8), 1));
    $c.util.getComponent('cal_edt_ToDate').setValue($c.date.formatDate("yyyymmdd"));
};

/**
 * @method
 * @name isDigitalCheck
 * @description is Digital Check 처리
 * @returns {void}
 * @hidden N
 */
scwin.isDigitalCheck = function () {
    const scr = scwin.getProvider();
    if (scr != null && scr != null && scr.vScrenID === "ULDSTF15660.gfm") {
        scwin.vDigitalYn = "Y";
        tab_corpinfo.DisableBackColor = "#999999";
        $c.util.getComponent('tab_corpinfo').setDisabled(!(false));
    }
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name showObj
 * @description 컴포넌트 표시/숨김(as-is 공통 showObj — id 문자열 또는 컴포넌트)
 * @param {Object} obj 컴포넌트 id 또는 컴포넌트
 * @param {String} flag true 표시 · false 숨김
 * @returns {void}
 * @hidden N
 */
scwin.showObj = function (obj, flag) {
    const comp = (typeof obj === "string") ? $c.util.getComponent(obj) : obj;
    if (!comp) { return; }
    if (flag) { comp.show(); } else { comp.hide(); }
};
